import math

def prime_fib(n: int):
    """
    Returns the n-th Fibonacci number that is also prime.
    """
    if n < 1:
        raise ValueError("n must be a positive integer")

    def is_prime(num: int) -> bool:
        if num < 2:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False
        limit = int(math.isqrt(num))
        for i in range(3, limit + 1, 2):
            if num % i == 0:
                return False
        return True

    a, b = 0, 1  # F(0), F(1)
    count = 0
    while True:
        # Next Fibonacci number
        c = a + b
        a, b = b, c
        if is_prime(c):
            count += 1
            if count == n:
                return c
