from collections import Counter

def pairs_sum_to_zero(l):
    """
    pairs_sum_to_zero takes a list of integers as an input.
    It returns True if there exist two distinct elements in the list
    that sum to zero, and False otherwise.
    """
    # Count occurrences of each number
    counts = Counter(l)
    # For each number x, check if -x exists (and is not the same element unless duplicated)
    for x in counts:
        if counts[x] > 0 and counts.get(-x, 0) > 0:
            # If x and -x are the same (x == 0), need at least 2 zeros
            if x == 0:
                if counts[0] >= 2:
                    return True
            else:
                if -x in counts:
                    return True
    return False
