import math

def prime_length(string):
    """
    Write a function that takes a string and returns True if the string
    length is a prime number or False otherwise
    Examples
    prime_length('Hello') == True  # len('Hello') = 5, which is prime
    prime_length('abcdcba') == True # len('abcdcba') = 7, which is prime
    prime_length('kittens') == True # len('kittens') = 7, which is prime
    prime_length('orange') == False # len('orange') = 6, not prime
    """
    def is_prime(n):
        if n <= 1:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        for i in range(3, int(math.sqrt(n)) + 1, 2):
            if n % i == 0:
                return False
        return True

    return is_prime(len(string))
